INSERT INTO question (id, subject, qtype, stem, options, answer, score, source) VALUES (2022001, 1, 1, '下列程序段的时间复杂度是 。 int sum = 0; for (int i = 1;i < n;i*=2) for(int j = 0;j < i;j++) sum++;', '[{"key": "A", "content": "O(log n)"}, {"key": "B", "content": "O(n)"}, {"key": "C", "content": "O(n log n)"}, {"key": "D", "content": "O(n 2 )"}]', 'B', 2.0, '2022-408-1');
INSERT INTO question (id, subject, qtype, stem, options, answer, score, source) VALUES (2022002, 1, 1, '给定有限符号集 S，in 和 out 均为 S 中所有元素的任意排列。对于初始为空的栈 ST，下列叙述 中，正确的是 。', '[{"key": "A", "content": "若 in 是 ST 的入栈序列，则不能判断 out 是否为其可能的出栈序列"}, {"key": "B", "content": "若 out 是 ST 的出栈序列，则不能判断 in 是否为其可能的入栈序列"}, {"key": "C", "content": "若 in 是 ST 的入栈序列，out 是对应 in 的出栈序列，则 in 与 out 一定不同"}, {"key": "D", "content": "若 in 是 ST 的入栈序列，out 是对应的出栈序列，则 in 与 out 可能互为倒序"}]', 'D', 2.0, '2022-408-2');
INSERT INTO question (id, subject, qtype, stem, options, answer, score, source) VALUES (2022003, 1, 1, '若结点 p 与 q 在二叉树 T 的中序遍历序列中相邻，且 p 在 q 之前，则下列 p 与 q 的关系中，不． 可能的是 。 I. q 是 p 的双亲 II. q 是 p 的右孩子 III. q 是 p 的右兄弟 IV . q是 p 的双亲的双亲', '[{"key": "A", "content": "仅 I"}, {"key": "B", "content": "仅 III"}, {"key": "C", "content": "仅 II、III"}, {"key": "D", "content": "仅 II、IV"}]', 'B', 2.0, '2022-408-3');
