INSERT INTO question (id, subject, qtype, stem, options, answer, score, source) VALUES (2022010, 1, 1, '使用二路归并排序对含 n 个元素的数组 M 进行排序时，二路归并操作的功能是 。', '[{"key": "A", "content": "将两个有序表合并为一个新的有序表"}, {"key": "B", "content": "将 M 划分为两部分，两部分的元素个数大致相等"}, {"key": "C", "content": "将 M 划分为 n 个部分，每个部分中仅含有一个元素"}, {"key": "D", "content": "将 M 划分为两部分，一部分元素的值均小于另一部分元素的值"}]', 'A', 2.0, '2022-408-10');
