INSERT INTO question (id, subject, qtype, stem, options, answer, score, source) VALUES (2022015, 2, 1, '某计算机主存地址为 24 位，采用分页虚拟存储管理方式，虚拟地址空间大小为 4 GB，页大小为 4KB，按字节编址。某进程的页表部分内容如下表所示。 虚页号 实页号（页框号） 存在位 82 024H 0 … … … 129 180H 1 130 018H 1 当 CPU 访问虚拟地址 0008 2840H 时，虚–实地址转换的结果是 。', '[{"key": "A", "content": "得到主存地址 02 4840H"}, {"key": "B", "content": "得到主存地址 18 0840H"}, {"key": "C", "content": "得到主存地址 01 8840H"}, {"key": "D", "content": "检测到缺页异常"}]', 'C', 2.0, '2022-408-15');
