INSERT INTO question (id, subject, qtype, stem, options, answer, score, source) VALUES (2022047, 4, 2, '某网络拓扑如题 47 图所示， R 为路由器，S 为以太网交换机，AP 是 802.11 接入点，路 由器的 E0 接口和 DHCP 服务器的 IP 地址配置如图中所示；H1 与 H2 属于同一个广播域，但不 属于同一个冲突域；H2 和 H3 属于同一个冲突域；H4 和 H5 已经接入网络，并通过 DHCP 动态 获取了 IP 地址。现有路由器、100BaseT 以太网交换机和 100BaseT 集线器（Hub）三类设备各若 干台。 题 47 题图 请回答下列问题。 51μs 的时间延迟，则 H2 与 H3 之间可以相距的最远距离是多少？ （3）在 H4 通过 DHCP 动态获取 IP 地址过程中，H4 首先发送了 DHCP 报文 M，M 是哪种 DHCP 报文？路由器 E0 接口能否收到封装 M 的以太网帧？S 向 DHCP 服务器转发的封装 M 的 以太网帧的目的 MAC 地址是什么？ （4）若 H4 向 H5 发送一个 IP 分组 P，则 H5 收到的封装 P 的 802.11 帧的地址 1、地址 2 和地址 3 分别是什么？', NULL, NULL, 9.0, '2022-408-47');
