INSERT INTO question (id, subject, qtype, stem, options, answer, score, source) VALUES (2023028, 3, 1, '对于采用虚拟内存管理方式的系统，下列关于进程虚拟地址空间的叙述中，错误的是 。', '[{"key": "A", "content": "每个进程都有自已独立的虚拟地址空间"}, {"key": "B", "content": "C 语言中 malloc()函数返回的是虚拟地址"}, {"key": "C", "content": "进程对数据段和代码段可以有不同的访问权限"}, {"key": "D", "content": "虚拟地址空间的大小由内存和硬盘的大小决定"}]', 'D', 2.0, '2023-408-28');
INSERT INTO question (id, subject, qtype, stem, options, answer, score, source) VALUES (2023029, 3, 1, '进程 P1、P2 和 P3 进入就绪队列的时刻， 优先级 （值越大优先权越高） 以及CPU 的执行时间如下 表所示： 进程名 进入就绪队列的时刻 优先数 CPU 执行时间 P1 0ms 1 60ms P2 20ms 10 42ms P3 30ms 100 13ms 若系统采用基于优先权的抢占式 CPU 调度算法，从 0ms 时刻开始进行调度，则 P1、P2 和 P3 的平均周转时间为 。', '[{"key": "A", "content": "60ms"}, {"key": "B", "content": "61ms"}, {"key": "C", "content": "70ms"}, {"key": "D", "content": "71ms"}]', 'B', 2.0, '2023-408-29');
INSERT INTO question (id, subject, qtype, stem, options, answer, score, source) VALUES (2023030, 3, 1, '进程 R 和 S 共享数据 data，若 data 在 R 和 S 中所在页的页号分别为 p1 和 p2，两个页所对应的页 框号分别为 f1 和 f2，则下列叙述中，正确的是 。', '[{"key": "A", "content": "p1 和 p2 一定相等，f1 和 f2 一定相等"}, {"key": "B", "content": "p 1 和 p2 一定相等，f1 和 f2 不一定相等"}, {"key": "C", "content": "p1 和 p2 不一定相等，f1 和 f2 一定相等"}, {"key": "D", "content": "p 1 和 p2 不一定相等，f1 和 f2 不一定相等"}]', 'C', 2.0, '2023-408-30');
INSERT INTO question (id, subject, qtype, stem, options, answer, score, source) VALUES (2023031, 3, 1, '若文件 F 仅被进程 P 打开并访问，则当进程 P 关闭 F 时，下列操作中，文件系统需要完成的 是 。', '[{"key": "A", "content": "删除目录文件中 F 的目录项"}, {"key": "B", "content": "释放 F 的索引节点所占的内存空间"}, {"key": "C", "content": "释放 F 的索引节点所占的外存空间"}, {"key": "D", "content": "将文件磁盘索引结点中的链接计数减 1"}]', 'B', 2.0, '2023-408-31');
