INSERT INTO question (id, subject, qtype, stem, options, answer, score, source) VALUES (2023033, 4, 1, '在下图所示的分组交换网络中，主机 H1 和 H2 通过路由器互连，2 段链路的带宽均为 100 Mb/s、 时延带宽积（即单向传播时延×宽带）均为 1000b。若 H1 向 H2 发送 1 个大小为 1 MB 的文件， 分组长度为 1000B， 则从H1 开始发送时刻起到 H2 收到文件全部数据时刻止， 所需的时间至少是 （注：M=10 6 ） 。', '[{"key": "A", "content": "80.02ms"}, {"key": "B", "content": "80.08ms"}, {"key": "C", "content": "80.09ms"}, {"key": "D", "content": "80.10ms"}]', 'D', 2.0, '2023-408-33');
INSERT INTO question (id, subject, qtype, stem, options, answer, score, source) VALUES (2023034, 4, 1, '某无噪声理想信道带宽为 4MHz，采用 QAM 调制，若该信道的最大数据传输速率是 48Mb/s，则 该信道采用的 QAM 调制方案是 。', '[{"key": "A", "content": "QAM–16"}, {"key": "B", "content": "QAM– 32"}, {"key": "C", "content": "QAM– 64"}, {"key": "D", "content": "QAM– 128"}]', 'C', 2.0, '2023-408-34');
INSERT INTO question (id, subject, qtype, stem, options, answer, score, source) VALUES (2023035, 4, 1, '假设通过同一信道，数据链路层分别采用停止–等待协议、GBN 协议和 SR 协议（发送窗口和接 收窗口相等） 传输数据， 3 个协议数据帧长相同， 忽略确认帧长度， 帧序号位数为 3 比特。 若对应 3 个协议的发送方最大信道利用率分别是 U1、U2 和 U3， 则U1、U2 和 U3 满足的关系是 。', '[{"key": "A", "content": "U1≤U2≤U3"}, {"key": "B", "content": "U 1≤U3≤U2"}, {"key": "C", "content": "U 2≤U3≤U1"}, {"key": "D", "content": "U 3≤U2≤U1"}]', 'B', 2.0, '2023-408-35');
INSERT INTO question (id, subject, qtype, stem, options, answer, score, source) VALUES (2023036, 4, 1, '已知 10BaseT 以太网的争用时间片为 51.2μs。若网卡在发送某帧时发生了连续 4 次冲突，则基于 二进制指数退避算法确定的再次尝试重发该帧前等待的最长时间是 。', '[{"key": "A", "content": "51.2μs"}, {"key": "B", "content": "204.8μs"}, {"key": "C", "content": "768μs"}, {"key": "D", "content": "819.2μs"}]', 'C', 2.0, '2023-408-36');
