INSERT INTO question (id, subject, qtype, stem, options, answer, score, source) VALUES (2023040, 4, 1, '下列关于 IPv4 和 IPv6 的叙述中，正确的是（ ） 。 I. IPv6 地址空间是 IPv4 地址空间的 96 倍 II. IPv4 首部和 IPv6 的基本首部的长度均可变 III. IPv4 向 IPv6 过渡可以采用双协议栈和隧道技术 IV . IPv6 首部的 Hop Limit 等价于 IPv4 首部的 TTL 字段', '[{"key": "A", "content": "仅 I、II"}, {"key": "B", "content": "仅 I、IV"}, {"key": "C", "content": "仅 II、III"}, {"key": "D", "content": "仅 III、IV"}]', 'D', 2.0, '2023-408-40');
INSERT INTO question (id, subject, qtype, stem, options, answer, score, source) VALUES (2023041, 1, 2, '已知有向图 G 采用邻接矩阵存储，类型定义如下： typedef struct       // 图的类型定义 { int numVertices, numEdges;  // 图的顶点数和有向边数 char VerticesList[MAXV];   // 顶点表，MAXV 为已定义常量 int Edge[MAXV][MAXV];   // 邻接矩阵 }MGraph 题 41 图 将图中出度大于入度的顶点称为 K 顶点。例如题 41 图中，顶点 a 和顶点 b 为 K 顶点。请设计算 法：int printVertices(MGraph G)，对给定的任意非空有向图 G，输出图 G 中所有的 K 顶点，并返回 K 顶点的个数。要求：', NULL, NULL, 13.0, '2023-408-41');
