INSERT INTO question (id, subject, qtype, stem, options, answer, score, source) VALUES (2023043, 2, 2, '已知计算机 M 字长为 32 位，按字节编址，采用请求调页策略的虚拟存储管理方式， 虚拟地址 32 位，页面大小为 4 KB；数据 Cache 采用 4 路组相联映射方式，数据区大小为 8 KB， 主存块大小为 32B。现有 C 语言程序段如下： int a[24][64]; … for (i=0;i<24;i++) for (j=0;j<64;j++)a[i][j]=10; 已知二维数组 a 按行优先存放，在虚拟地址空间中分配的起始地址为 0042 2000H，sizeof(int) = 4。假定在 M 上执行上述程序段之前数组 a 不在主存，且在该程序执行过程中不会发生页面置 换。请回答下列问题：', NULL, NULL, 14.0, '2023-408-43');
INSERT INTO question (id, subject, qtype, stem, options, answer, score, source) VALUES (2023044, 2, 2, '43 题中 C 程序段在计算机 M 上的部分机器级代码如下，每个机器级代码行中依次包含 指令序号、虚拟地址、机器指令和汇编指令。 for (i=0 ; i<24; i++) 1 00401072 C7 45 F8 00 00 00 00  mov [ebp–8] ，0 2 00401079 EB 09       jmp 00401084h 3 0040107B 8B 55 F8      mov eax ，[ebp-8] ...   ...        ... 7 00401088 7D 32       jge 004010BCh for (j=0 ; j<64; j++) 8 0040108A C7 45 FC 00 00 00 00  mov [ebp–4] ，0 ...   ...        ... a[i][j]=10 ; ...   ...        ... 19 004010AE C7 84 82 00 20 42 00 0A  mov [ecx + edx * 4+ 00 00 00      00422000h] ，0Ah 请回答下列问题。', NULL, NULL, 9.0, '2023-408-44');
INSERT INTO question (id, subject, qtype, stem, options, answer, score, source) VALUES (2023045, 3, 2, '现要求学生使用 swap 指令和布尔型变量 lock，实现临界区互斥。lock 为线程间共享的 变量。lock 的值为 TRUE 时线程不能进入临界区，为 FALSE 时，线程能进入临界区。某同学编 写的实现临界区互斥的伪代码如题 45（a）图所示：请回答下列问题。 某同学写的伪代码  newSwap() 的代码 bool lock=false;   // 共享变量 ...... bool key=True if(key == TRUE) swap key,lock; 进入区 临界区 lock=TRUE; 退出区 void newSwap(bool*a, bool*b) { bool temp=*a *a=*b; *b=temp; } 题 45(a)图  题 45(b)图 请回答下列问题：', NULL, NULL, 7.0, '2023-408-45');
INSERT INTO question (id, subject, qtype, stem, options, answer, score, source) VALUES (2023046, 3, 2, '进程 P 通过执行系统调用从键盘接收一个字符的输入，已知此过程中与进程 P 相关的操 作包括： ①将进程 P 插入就绪队列；②将进程 P 插入阻塞队列；③将字符从键盘控制器读入系统缓冲 区；④启动键盘中断处理程序；⑤进程 P 系统调用返回；⑥用户在键盘上输入字符。以上编号 ①～⑥仅用于标记操作，与操作的先后顺序无关，请回答下列问题。', NULL, NULL, 8.0, '2023-408-46');
INSERT INTO question (id, subject, qtype, stem, options, answer, score, source) VALUES (2023047, 4, 2, '某网络拓扑如题 47 图所示，主机 H 登录 FTP 服务器后，向服务器上传一个大小为 18000B 的文件 F。假设 H 为传输 F 建立数据连接时，选择的初始序号为 100，MSS=1000B，拥 塞控制初始阈值为 4MSS，RTT=10ms，忽略 TCP 段的传输时延；在 F 的传输过程中，H 均以 MSS 段向服务器发送数据，且未发生差错、丢包和乱序现象。 题 47 题图 请回答下列问题。', NULL, NULL, 9.0, '2023-408-47');
INSERT INTO question (id, subject, qtype, stem, options, answer, score, source) VALUES (2024001, 1, 1, '已知带头结点的非空单链表 L 的头指针为 h，结点结构为 data next ，其中 next 是指向直接后继 结点的指针。现有指针 p 和 q，若 p 指向 L 中非首且非尾的任意 一个结点。则执行语句序列 “q=p->next; p->next=q->next; q->next=h->next; h->next=q;”的结果是 。', '[{"key": "A", "content": "在 p 所指结点后插入 q 所指结点"}, {"key": "B", "content": "在 q 所指结点后插入 p 所指结点"}, {"key": "C", "content": "将 p 所指结点移动到 L 的头结点之后"}, {"key": "D", "content": "将 q 所指结点移动到 L 的头结点之后"}]', 'D', 2.0, '2024-408-1');
