INSERT INTO question (id, subject, qtype, stem, options, answer, score, source) VALUES (2024037, 4, 1, '主机甲通过选择重传（SR）滑动窗口协议向主机乙发送帧的部分过程如题 37 图所示，Fx 为数据 帧，ACKx 为确认帧，x 是位数为 3 比特的序号。 乙只对正确接收的数据帧进行独立确认， 发送窗 口与接收窗口大小相同且均为最大值。甲在 t1 时刻和 t2 时刻发送的数据帧分别是 。', '[{"key": "A", "content": "F1, F3"}, {"key": "B", "content": "F1, F4"}, {"key": "C", "content": "F3, F1"}, {"key": "D", "content": "F4, F1"}]', 'D', 2.0, '2024-408-37');
INSERT INTO question (id, subject, qtype, stem, options, answer, score, source) VALUES (2024038, 4, 1, '假设主机 H 通过 TCP 向服务器发送长度为 3000B 的报文，往返时间 RTT=10ms，最长报文段寿 命 MSL=30s，最大报文段长度 MSS=1 000B，忽略 TCP 段的传输时延，报文传输结束后 H 首先 请求断开连接，则从 H 请求建立 TCP 连接时刻起，到 H 进入 CLOSED 状态为止，所需的时间 至少是 。', '[{"key": "A", "content": "30.03s"}, {"key": "B", "content": "30.04s"}, {"key": "C", "content": "60.03s"}, {"key": "D", "content": "60.04s"}]', 'D', 2.0, '2024-408-38');
INSERT INTO question (id, subject, qtype, stem, options, answer, score, source) VALUES (2024039, 4, 1, '若 UDP 协议在计算校验和过程中，计算得到中间结果为 1011 1001 1011 0110 时，还需要加上最 后一个 16 位数 0110 0101 1100 0101，则最终计算得到的校验和是 。', '[{"key": "A", "content": "0001 1111 0111 1011"}, {"key": "B", "content": "0001 1111 0111 1100"}, {"key": "C", "content": "1110 0000 1000 0011"}, {"key": "D", "content": "1110 0000 1000 0100"}]', 'C', 2.0, '2024-408-39');
INSERT INTO question (id, subject, qtype, stem, options, answer, score, source) VALUES (2024040, 4, 1, '若浏览器不支持并行 TCP 连接，使用非持久的 HTTP/1.0 协议请求浏览 1 个 Web 页，该顶中引 用同一网站上 7 个小图像文件，则从浏览器为传输 Web 页请求建立 TCP 连接开始，到接收完所 有内容为止，所需要的往返时间 RTT 数至少是 。', '[{"key": "A", "content": "4"}, {"key": "B", "content": "9"}, {"key": "C", "content": "14"}, {"key": "D", "content": "16"}]', 'D', 2.0, '2024-408-40');
INSERT INTO question (id, subject, qtype, stem, options, answer, score, source) VALUES (2024041, 1, 2, '2023 年 10 月 26 日，神舟十七号载人飞船发射取得圆满成功，再次彰显了中国航天事 业的辉煌成就。载人航天工程是包含众多子工程的复杂系统工程，为了保证工程的有序开展，需 要明确各子工程的前导子工程，以协调各子工程的实施。该问题可以简化、抽象为有向图的拓扑 序列问题。已知有向图 G 采用邻接矩阵存储，类型定义如下。 typedef struct       //图的类型定义 { int numVertices, numEdges;  //图的顶点数和有向边数 char VerticesList[MAXV];   //顶点表，MAXV 为已定义常量 int Edge[MAXV][MAXV];   //邻接矩阵 }MGraph; 请设计算法：int uniquely(MGraph G)，判定 G 是否存在唯一的拓扑序列，若是，则返回 1，否则返回 0。要求如下。', NULL, NULL, 13.0, '2024-408-41');
INSERT INTO question (id, subject, qtype, stem, options, answer, score, source) VALUES (2024042, 1, 2, '将关键字序列 20, 3, 11, 18, 9, 14, 7 依次存储到初始为空、长度为 11 的散列表 HT 中， 散列函数 H(key) = (key×3)%11。H(key)计算出的初始散列地址为 H0，发生冲突时探查地址序列 是 H1, H2, H3, …，其中，Hk=(H0 + k 2 )%11，k = 1, 2, 3, …。 请回答下列问题。', NULL, NULL, 10.0, '2024-408-42');
INSERT INTO question (id, subject, qtype, stem, options, answer, score, source) VALUES (2024043, 2, 2, '假定计算机 M 字长为 32 位，按字节编址，采用 32 位定长指令字，指令 add、slli 和 lw 的格式、编码和功能说明如题 43 图（a）所示。 指令 31 25 24 20 19 15 14 12 11 7 6 0 指令功能说明 add 0000000 rs2 rs1 000 rd 0110011 R[rd]←R[rs1] + R[rs2] slli 0000000 shamt rs1 010 rd 0010011 R[rd]←R[rs1] <<shamt lw imm rs1 010 rd 0000011 R[rd]←M[R[rs1]+imm] 题 43 图（a） 其中，R[x]表示通用寄存器 x 的内容，M[x]表示地址为 x 的存储单元内容，shamt 为移位位数， imm 为补码表示的偏移量。题 43 图（b）给出了计算机 M 的部分数据通路及其控制信号（用带 箭头虚线表示），其中，A 和 B 分别表示从通用寄存器 rs1 和 rs2 中读出的内容；IR[31:20]表示指 存器中的高 12 位；控制信号 Ext 为 0、1 时扩展器分别实现零扩展、符号扩展，ALUctr 为 000、 001、010 时 ALU 分别实现加、减、逻辑左移运算。 题 43 图（b） 请回答下列问题。', NULL, NULL, 13.0, '2024-408-43');
INSERT INTO question (id, subject, qtype, stem, options, answer, score, source) VALUES (2024044, 2, 2, '对于题 43 中的计算机 M，C 语言程序 P 包含的语句“sum+=a[i];”在 M 中对应的指令 序列 S 如下。 slli  r4, r2, 2   //R[r4]←R[r2]<<2 add  r4, r3, r4  //R[r4]←R[r3]+R[r4] lw  r5, 0(r4)   //R[r5]←M[R[r4]+0] add  r1, r1, r5  //R[r1]←R[r1]+R[r5] 已知变量 i、sum 和数组 a 都为 int 型，通用寄存器 r1~r5 的编号为 01H～05H。 请回答下列问题。', NULL, NULL, 10.0, '2024-408-44');
INSERT INTO question (id, subject, qtype, stem, options, answer, score, source) VALUES (2024045, 3, 2, '某计算机按字节编址，采用页式虚拟存储管理方式，虚拟地址和物理地址的长度均为 32 位，页表项的大小为 4 字节，页大小为 4 MB，虚拟地址结构如下。 页号（10 位） 页内偏移量（22 位） 进程 P 的页表起始虚拟地址为 B8C0 0000H，被装载到从物理地址 6540 0000H 开始的连续主存空 间中。 请回答下列问题，要求答案用十六进制表示。', NULL, NULL, 7.0, '2024-408-45');
INSERT INTO question (id, subject, qtype, stem, options, answer, score, source) VALUES (2024046, 3, 2, '计算机系统中的进程之间往往需要相互协作以完成一个任务。在某网络系统中，缓冲区 B 用于存放一个数据分组，对 B 的操作有 C1、C2 和 C3。C1 将一个数据分组写入 B 中，C2 从 B 中读出一个数据分组，C3 对 B 中的数据分组进行修改。要求 B 为空时才能执行 C1，B 非空时 才能执行 C2 和 C3。', NULL, NULL, 8.0, '2024-408-46');
INSERT INTO question (id, subject, qtype, stem, options, answer, score, source) VALUES (2024047, 4, 2, '网络空间是继陆海空天之后的“第五疆域” ，网络技术是网络疆域建设与治理的基础。 路由算法与协议是网络核心技术之一，对其准确认知、合理选择与应用，对于网络建设十分重 要。假设现有互联网中的 4 个自治系统互连拓扑示意图如题 47 图所示。其中，AS1 运行内部网 关协议 RIP；AS3 规模较小，自治系统内任意两个主机间通信，经过路由器数量不超过 15 个； AS4 规模较大，自治系统内任意两个主机间通信，经过路由器数量可能超过 20 个。 题 47 题图 请回答下列问题。', NULL, NULL, 9.0, '2024-408-47');
INSERT INTO question (id, subject, qtype, stem, options, answer, score, source) VALUES (2025001, 1, 1, '下列程序段的时间复杂度是 。 int count=0, i, j; for(i=1; i*i<=n; i++) for(j=1; j<=i; j++) count ++;', '[{"key": "A", "content": "O(log n)"}, {"key": "B", "content": "O(n)"}, {"key": "C", "content": "O(n log n)"}, {"key": "D", "content": "O(n 2 )"}]', 'B', 2.0, '2025-408-1');
INSERT INTO question (id, subject, qtype, stem, options, answer, score, source) VALUES (2025002, 1, 1, '已知算法 A用于检查字符串中各类括号是否匹配，A执行过程中使用初始为空的栈保存遇到的括 号。若栈的容量是 3，则下列选项中，A不能．．处理的是 。', '[{"key": "A", "content": "(a + [b + (c + d) / e] + f) + g – h"}, {"key": "B", "content": "[a * ((b + c) / (d – e) + f / g) - h]"}, {"key": "C", "content": "[a * (b – (c – d) * e / (f + g)) – h]"}, {"key": "D", "content": "[a – (b + [c * (d + e) – f] + g + h)]"}]', 'D', 2.0, '2025-408-2');
