INSERT INTO question (id, subject, qtype, stem, options, answer, score, source) VALUES (2025029, 3, 1, '某文件系统采用目录和索引节点管理文件，当用户在目录中新建文件 F 时，下列操作中，文件系 统不会．．做的是 。', '[{"key": "A", "content": "对 F 的索引节点进行初始化"}, {"key": "B", "content": "在目录文件中写入 F 的索引节点号"}, {"key": "C", "content": "在目录文件中写入 F 的访问权限信息"}, {"key": "D", "content": "在目录文件中增加一条 F 对应的目录项"}]', 'C', 2.0, '2025-408-29');
INSERT INTO question (id, subject, qtype, stem, options, answer, score, source) VALUES (2025030, 3, 1, '下列关于内存映射文件（memory-mapped files）机制的叙述中，正确的是 。 I. 可实现进程之间的通信 II. 可实现页到磁盘块的映射 III. 将文件映射到进程的虚拟地址空间 IV . 将文件映射到系统的物理地址空间', '[{"key": "A", "content": "仅 I、III"}, {"key": "B", "content": "仅 I、IV"}, {"key": "C", "content": "仅 II、III"}, {"key": "D", "content": "仅 I、II、III"}]', 'A', 2.0, '2025-408-30');
INSERT INTO question (id, subject, qtype, stem, options, answer, score, source) VALUES (2025031, 3, 1, '下列选项中，文件系统可用于记录外存空闲空间使用情况的是 。', '[{"key": "A", "content": "目录"}, {"key": "B", "content": "系统打开文件表"}, {"key": "C", "content": "文件分配表（FAT）"}, {"key": "D", "content": "文件控制块（FCB）"}]', 'C', 2.0, '2025-408-31');
INSERT INTO question (id, subject, qtype, stem, options, answer, score, source) VALUES (2025032, 3, 1, '下列选项中，文件系统需要为温彻斯特硬盘和固态硬盘都提供的功能是 。', '[{"key": "A", "content": "划分扇区"}, {"key": "B", "content": "确定盘块大小"}, {"key": "C", "content": "降低寻道时间"}, {"key": "D", "content": "实现均衡磨损"}]', 'B', 2.0, '2025-408-32');
INSERT INTO question (id, subject, qtype, stem, options, answer, score, source) VALUES (2025033, 4, 1, '某网络拓扑及各链路带宽如题 33 图所示。网络按电路交换方式运行时，主机H1 与H2 建立一条 带宽为 10Mb/s 的电路，建立电路时间为 32μs；按分组交换方式运行时，分组长度为 400B，忽略 分组首部开销。现 H1 向H2 发送一个 2MB（1M = 10 6 ）的文件，分别采用电路交换、报文交换、 分组交换方式时，H2 至少需要TCS、TMS、TPS时间才能接收到全部文件内容，则 TCS、TMS、TPS满 足的关系是 题 33 图', '[{"key": "A", "content": "TCS > TMS > TPS"}, {"key": "B", "content": "TMS > TPS > TCS"}, {"key": "C", "content": "TMS > TCS > TPS"}, {"key": "D", "content": "TPS > TMS > TCS"}]', 'B', 2.0, '2025-408-33');
INSERT INTO question (id, subject, qtype, stem, options, answer, score, source) VALUES (2025034, 4, 1, '若某差错编码的编码集为{1001 1010, 0101 1100, 1111 0000, 0000 1111}，则该差错编码的检错和纠 错能力是', '[{"key": "A", "content": "不超过 2 位错的 100%检错、不超过 1 位错的纠错"}, {"key": "B", "content": "不超过 2 位错的 100%检错、不超过 2 位错的纠错"}, {"key": "C", "content": "不超过 3 位错的 100%检错、不超过 1 位错的纠错"}, {"key": "D", "content": "不超过 3 位错的 100%检错、不超过 2 位错的纠错"}]', 'C', 2.0, '2025-408-34');
INSERT INTO question (id, subject, qtype, stem, options, answer, score, source) VALUES (2025035, 4, 1, '在某个 10BaseT以太网的冲突域内，若主机甲向主机乙发送数据帧时发生了连续 11 次冲突，则甲 再次尝试发送该数据帧的最大间隔时间是 。', '[{"key": "A", "content": "0.512ms"}, {"key": "B", "content": "0.5632ms"}, {"key": "C", "content": "52.3776ms"}, {"key": "D", "content": "104.8064ms"}]', 'C', 2.0, '2025-408-35');
INSERT INTO question (id, subject, qtype, stem, options, answer, score, source) VALUES (2025036, 4, 1, '一台新接入网络的主机 H通过 DHCP服务器动态请求 IP地址过程中， 与DHCP服务器交换 DHCP 报文的部分过程如题 36 图所示。封装DHCPREQUEST 报文的 IP 数据报的目的 IP 地址和源 IP 地 址分别是 题 36 图', '[{"key": "A", "content": "192.168.5.1, 0.0.0.0"}, {"key": "B", "content": "192.168.5.1, 192.168.5.9"}, {"key": "C", "content": "255.255.255.255, 0.0.0.0"}, {"key": "D", "content": "255.255.255.255, 192.168.5.9"}]', 'C', 2.0, '2025-408-36');
INSERT INTO question (id, subject, qtype, stem, options, answer, score, source) VALUES (2025037, 4, 1, '假设路由器实现 NAT功能， 内网中主机H的 IP 地址为 192.168.1.5/24。 若H运行某应用向 Internet 发送了一个 UDP 报文段，则路由器在转发封装该 UDP 报文段的 IP 数据报的过程中，UDP 报文 段的首部字段会被修改的是 I. 源端口号 II. 目的端口号 III. 总长度 IV . 校验和', '[{"key": "A", "content": "仅 I、III"}, {"key": "B", "content": "仅 I、IV"}, {"key": "C", "content": "仅 II、III"}, {"key": "D", "content": "仅 II、IV"}]', 'B', 2.0, '2025-408-37');
INSERT INTO question (id, subject, qtype, stem, options, answer, score, source) VALUES (2025038, 4, 1, '主机甲通过 TCP 向主机乙发送数据的部分过程如题 38 图所示，seq为序号，ack_seq为确认序号， rcvwnd 为接收窗口。甲在 t0 时刻的拥塞窗口和发送窗口均为 2000B，拥塞控制值为 8000B， MSS=1000B，甲始终以 MSS 发送 TCP 段。若甲在 t1时刻收到如图所示的确认段，则甲在未收到 新的确认段之前，还可以继续向乙发送的 TCP 段数是 题 38 图', '[{"key": "A", "content": "2"}, {"key": "B", "content": "3"}, {"key": "C", "content": "4"}, {"key": "D", "content": "5"}]', 'A', 2.0, '2025-408-38');
INSERT INTO question (id, subject, qtype, stem, options, answer, score, source) VALUES (2025039, 4, 1, 'Time 是一个提供时间查询服务的 C/S 架构网络应用，支持客户通过 UDP 或 TCP 向 Time 服务器 请求时间服务。若某客户与某Time服务器通信的往返时间 RTT=8ms，则该客户分别通过UDP和 TCP 向该服务器请求服务，所需的最少时间分别是', '[{"key": "A", "content": "8ms, 8ms"}, {"key": "B", "content": "8ms, 16ms"}, {"key": "C", "content": "16ms, 8ms"}, {"key": "D", "content": "16ms, 16ms"}]', 'B', 2.0, '2025-408-39');
INSERT INTO question (id, subject, qtype, stem, options, answer, score, source) VALUES (2025040, 4, 1, '下列关于 POP3 协议的叙述中，正确的是 I. 支持用户代理从邮件服务器读取邮件 II. 支持用户代理向邮件服务器发送邮件 III. 支持邮件服务器之间发送与接收邮件 IV . 支持通过一条 TCP 连接收取多封邮件', '[{"key": "A", "content": "仅 I、IV"}, {"key": "B", "content": "仅 II、III"}, {"key": "C", "content": "仅 I、II、III"}, {"key": "D", "content": "仅 I、III、IV"}]', 'A', 2.0, '2025-408-40');
INSERT INTO question (id, subject, qtype, stem, options, answer, score, source) VALUES (2025041, 1, 2, '（本题 13 分）设有两个长度均为n的一维整型数组 A和 res，对数组 A中的每个元素 A[i]，计算 A[i]与 A[j]（0 ≤ i ≤ j ≤ n – 1）乘积的最大值，并将其保存到 res[i]中。例如，若 A[]={1, 4, –9, 6}，则得到 res[]={6, 24, 81, 36}。现给定数组 A请设计一个时间和空间上尽可能高效的算法 calMulMax，求 res中各元素的值。函数原型为：void calMulMax(int A[], int res[], int n)。要求如下。', NULL, NULL, 13.0, '2025-408-41');
INSERT INTO question (id, subject, qtype, stem, options, answer, score, source) VALUES (2025042, 1, 2, '（本题 10 分）某工程包含 12 个活动，使用题 42 图所示的AOE网描述，图中各边上标注了活动 及其持续时间。 题 42 图 请回答下列问题（活动均用活动名表示） 。', NULL, NULL, 10.0, '2025-408-42');
INSERT INTO question (id, subject, qtype, stem, options, answer, score, source) VALUES (2025043, 2, 2, '（本题 12 分）现有C 语言程序 P 的部分代码如题 43 图所示。假定运行程序P 的计算机 M 字长 为 32 位，按字节编址，数据Cache的数据区大小为 32KB，采用 8 路组相联映射方式，主存块 大小为 64B，Cache的命中时间为 2 个时钟周期，缺失损失为 200 个时钟周期；采用页式虚拟存 储管理方式，页大小为 4KB。数组 d的起始虚拟地址 V A31～V A0，为 0180 0020H。 int x, d[2048], i; ... for(i=0; i<2048; i++) d[i]=d[i]/x; ... 题 43 图 请回答下列问题。', NULL, NULL, 13.0, '2025-408-43');
INSERT INTO question (id, subject, qtype, stem, options, answer, score, source) VALUES (2025044, 2, 2, '（本题 11 分）对于题 43 中计算机M 和程序 P，假定 P 的部分机器级代码如题 44 图（a）所 示，其中，R0～R4 为通用寄存器，SEXT 表示按符号扩展；M 中补码除法器逻辑结构如题 44 图 （b）所示。 ... //x在R2中，i在R4中 //数组d的首地址在R3中 mov   R1, (R3+R4*4)  //R1←d[i] scov  R1               //{R0, R1}←SEXT(R1) idiv  R1, R2          //R1←{R0, R1}/R2 ... 题 44 图（a） 题 44 图（b） 请回答下列问题。', NULL, NULL, 10.0, '2025-408-44');
INSERT INTO question (id, subject, qtype, stem, options, answer, score, source) VALUES (2025045, 3, 2, '（本题 7 分）甲、乙、丙三人一起植树，甲负责挖树坑，乙负责将树苗放入树坑中并填土，丙负 责为新种的树苗浇水。植树的步骤依次为：挖树坑、放树苗、填土和浇水。现有铁锹和水桶各 1 个，铁锹用于挖树坑和填土，水桶用于浇水。当树坑的数量小于 3 时，甲才可以挖树坑。假设初 始时树坑的数量为 0，铁锹和水桶均可用。请定义尽可能少的信号量，用wait()、signal()操作描 述植树过程中三人之间的同步或互斥关系，并说明所用信号量的作用及其初值。', NULL, NULL, 7.0, '2025-408-45');
INSERT INTO question (id, subject, qtype, stem, options, answer, score, source) VALUES (2025046, 3, 2, '（本题 8 分）某系统中进程的虚拟地址空间包括内核区、用户栈运行时堆、可读写数据段、只读 代码段等区域，其布局如题 46 图所示，图中阴影部分表示未占用区域。现有C 语言程序的部分 代码如下。 char *ptr; void main() { int length; ptr=(char *)malloc(100); scanf("%s", ptr); length=strlen(ptr); printf("length=%d\\n", length); free(ptr); } 题 46 图 请回答下列问题。', NULL, NULL, 8.0, '2025-408-46');
INSERT INTO question (id, subject, qtype, stem, options, answer, score, source) VALUES (2025047, 4, 2, '（本题 9 分）某公司在承建国家重大工程项目时，工程部需要较长时间驻扎在偏远山区，工程部 网络需要连接公司总部网络。假设综合考虑方案的技术可行性、安全性与经济成本等因素后，决 定租用我国自主建设的天通一号卫星通信链路，连接工程部网络的路由器 R1 和公司总部网络的 路由器 R2，如题 47 图所示。S1 和S2 为千兆以太网交换机；TR1 和TR2 是卫星信号地面收发设 备， 实现全双工调制解调。 天通一号卫星轨道高度是 36 000km， 电磁波信号传播速度为 300 000km/s。 租用的卫星链路为 R1 和R2 之间提供对称全双工信道，每个方向的数据传输速率为 200kb/s。 题 47 题图 请回答下列问题。', NULL, NULL, 9.0, '2025-408-47');
INSERT INTO question (id, subject, qtype, stem, options, answer, score, source) VALUES (2026001, 1, 1, '线性表 L 含有 n ( n≥3)个元素，采用顺序存储方式保存。在 L 中原有元素相对次序保持不变且仍 有空闲存储空间的情况下，下列操作中，一定会移动多个元素的是 。 I. 在表头插入一个元素 II. 在表头删除一个元素 III. 在表尾插入一个元素 IV . 在表尾删除一个元素', '[{"key": "A", "content": "仅 I、II"}, {"key": "B", "content": "仅 I、III"}, {"key": "C", "content": "仅 II、IV"}, {"key": "D", "content": "仅 III、IV"}]', 'A', 2.0, '2026-408-1');
INSERT INTO question (id, subject, qtype, stem, options, answer, score, source) VALUES (2026002, 1, 1, '已知带头结点的双向链表 L 含有 n (n≥3)个元素，结点结构为 p2 d p1 ，其中，p2 和p1 分别 是指向其直接前驱和直接后继结点的指针，指针 head 指向头结点，指针 cu=head。现要将 L 各结 点中的 p2 指针修改为指向p1 所指结点的直接后继结点。当指针指向的结点不存在时，相应的指 针值为 NULL。下列选项中，可以完成修改功能的是 。', '[{"key": "A", "content": "while(cu!=NULL){cu->p2=cu->p1->p1;cu=cu->p1;}"}, {"key": "B", "content": "while(cu!=NULL&&cu->p2!=NULL){cu->p2=cu->p1->p1;cu=cu->p1;}"}, {"key": "C", "content": "while(cu!=NULL){if(cu->p1!=NULL){cu->p2=cu->p1->p1;cu=cu->p1;}}"}, {"key": "D", "content": "while(cu!=NULL){if(cu->p1!=NULL) cu->p2=cu->p1->p1; else cu->p2=NULL; cu=cu->p1;}"}]', 'D', 2.0, '2026-408-2');
INSERT INTO question (id, subject, qtype, stem, options, answer, score, source) VALUES (2026003, 1, 1, '若二叉树 T 的中序遍历序列是 b, e, d, f, c, a, g，层序遍历序列是 a, b, g, c, d, e, f，则 T 的后序遍历 序列是 。', '[{"key": "A", "content": "c, e, d, f, b, g, a"}, {"key": "B", "content": "c, e, f, d, b, g, a"}, {"key": "C", "content": "e, f, d, c, b, g, a"}, {"key": "D", "content": "e, g, f, d, b, c, a"}]', 'C', 2.0, '2026-408-3');
INSERT INTO question (id, subject, qtype, stem, options, answer, score, source) VALUES (2026004, 1, 1, '已知由 5 棵树组成的森林F中各棵树所含的结点个数分别是 2, 3, 4, 5, 7。若 F中各棵树的排列次 序任意，则与 F 对应的二叉树的高度至少是 。', '[{"key": "A", "content": "5"}, {"key": "B", "content": "6"}, {"key": "C", "content": "8"}, {"key": "D", "content": "10"}]', 'B', 2.0, '2026-408-4');
INSERT INTO question (id, subject, qtype, stem, options, answer, score, source) VALUES (2026005, 1, 1, '已知二叉树 T 中 7 个叶结点a, b, c, d, e, f, g的权值分别是 1, 2, 4, 5, 8, 10, 12，当 T 的带权路径长 度最小时，与结点 e深度相同的叶结点仅有 。', '[{"key": "A", "content": "d"}, {"key": "B", "content": "g"}, {"key": "C", "content": "d、f"}, {"key": "D", "content": "f、g"}]', 'D', 2.0, '2026-408-5');
INSERT INTO question (id, subject, qtype, stem, options, answer, score, source) VALUES (2026006, 1, 1, '若用邻接表保存有向图 G=(V , E)，则计算 G 中某顶点入度的时间复杂度是 。', '[{"key": "A", "content": "O(|V|)"}, {"key": "B", "content": "O(min(|V|, |E|))"}, {"key": "C", "content": "O(|E|)"}, {"key": "D", "content": "O(max(|V|, |E|))"}]', 'D', 2.0, '2026-408-6');
INSERT INTO question (id, subject, qtype, stem, options, answer, score, source) VALUES (2026007, 1, 1, '有向图 G = (V , E)的顶点个数为 n(n≥2)，指定一个顶点为初始点，指定若干个顶点（非初始点） 为标记点，且每个顶点都在从初始点到标记点的有向路径上（一条有向路径上允许含有多个标记 点） 。每条有向边上均有一个字符，从初始点到任一标记点的有向路径上的所有字符组成一个字符 串，所有这样的字符串构成字符串集 S。下列关于 S的叙述中，错误．．的是 。', '[{"key": "A", "content": "若 G无环，则 S是有穷集"}, {"key": "B", "content": "若 G无环，则 S中存在长度等于 n的字符串"}, {"key": "C", "content": "若 G有环，则 S中存在长度大于 n的字符串"}, {"key": "D", "content": "若 G有环，则 S中存在长度小于 2n的字符串"}]', 'B', 2.0, '2026-408-7');
INSERT INTO question (id, subject, qtype, stem, options, answer, score, source) VALUES (2026008, 1, 1, '高度为 4 的平衡二叉树中，根结点左、右子树的结点个数相差最多是 。', '[{"key": "A", "content": "1"}, {"key": "B", "content": "2"}, {"key": "C", "content": "3"}, {"key": "D", "content": "4"}]', 'D', 2.0, '2026-408-8');
INSERT INTO question (id, subject, qtype, stem, options, answer, score, source) VALUES (2026009, 1, 1, '使用直接插入排序算法分别对下列数据进行升序排序，元素之间比较次数最少的是 。', '[{"key": "A", "content": "30, 27, 56, 41, 80, 95, 69"}, {"key": "B", "content": "31, 43, 26, 55, 63, 99, 77"}, {"key": "C", "content": "61, 84, 51, 23, 34, 91, 40"}, {"key": "D", "content": "93, 32, 48, 81, 50, 21, 72"}]', 'B', 2.0, '2026-408-9');
INSERT INTO question (id, subject, qtype, stem, options, answer, score, source) VALUES (2026010, 1, 1, '某考试考查了课程 C1 和C2，C1、C2成绩及总成绩 （C1、C2 成绩之和）均保存在数组M中。现 需根据考生的总成绩从高到低进行排名，总成绩相同者的排名由 C1 成绩从高到低决定，C1 成绩 也相同者的排名由初始相对次序决定。假设先按 C1 成绩对M排序，再按总成绩对 M排序，能得 到正确的排名结果，则下列算法中，采用的是 。', '[{"key": "A", "content": "基数排序"}, {"key": "B", "content": "快速排序"}, {"key": "C", "content": "希尔排序"}, {"key": "D", "content": "选择排序"}]', 'A', 2.0, '2026-408-10');
INSERT INTO question (id, subject, qtype, stem, options, answer, score, source) VALUES (2026011, 1, 1, '采用 k-路归并对外存中保存的数据进行排序， 排序的趟数记为d。 下列叙述中， 正确的是 。 I. 增大 k的值可能减小 d的值 II. 初始归并段的个数不影响 d的值 III. 可用内存大小限制了初始归并段的最大长度', '[{"key": "A", "content": "仅 I"}, {"key": "B", "content": "仅 I、II"}, {"key": "C", "content": "仅 I、III"}, {"key": "D", "content": "仅 II、III"}]', 'A', 2.0, '2026-408-11');
INSERT INTO question (id, subject, qtype, stem, options, answer, score, source) VALUES (2026012, 2, 1, '下列关于计算机系统层次结构的叙述中，错误．．的是 。', '[{"key": "A", "content": "最上层是应用软件层，最下层是器件及物理封装层"}, {"key": "B", "content": "指令集体系结构是软件和硬件之间的接口，且必不可少"}, {"key": "C", "content": "计算机组成（即微架构）属于指令集体系结构的物理实现层"}, {"key": "D", "content": "操作系统可通过指令集体系结构进行相应抽象，向上层软件提供服务"}]', 'C', 2.0, '2026-408-12');
INSERT INTO question (id, subject, qtype, stem, options, answer, score, source) VALUES (2026013, 2, 1, '对机器数 1010 0110B 先算术右移 3 位，再算术左移 2 位，最终结果是 。', '[{"key": "A", "content": "1101 0000B"}, {"key": "B", "content": "1101 0011B"}, {"key": "C", "content": "0101 0000B"}, {"key": "D", "content": "0101 0011B"}]', 'A', 2.0, '2026-408-13');
INSERT INTO question (id, subject, qtype, stem, options, answer, score, source) VALUES (2026014, 2, 1, '已知 float型变量用 IEEE 754单精度浮点格式表示，采用就近舍入 （中间值取偶数）方式。若 float 型变量 x值为 12.1 （提示：0.1 = 0.000 1100 1100 1100 1100 1100…B） ，则x的机器数是 。', '[{"key": "A", "content": "4141 9999H"}, {"key": "B", "content": "4141 999AH"}, {"key": "C", "content": "41E0 CCCCH"}, {"key": "D", "content": "41E0 CCCDH"}]', 'B', 2.0, '2026-408-14');
INSERT INTO question (id, subject, qtype, stem, options, answer, score, source) VALUES (2026015, 2, 1, '若用 8 个 64M×8 位的DRAM 芯片按交叉编址方式构成主存储器，并与一个宽度为 64 位的存储 器总线相连，主存每次最多读写 64 位，且按字节编址，则下列地址中，与主存地址 0018 001DH 位于同一芯片中的是 。', '[{"key": "A", "content": "0000 01D5H"}, {"key": "B", "content": "000F A020H"}, {"key": "C", "content": "0018 001EH"}, {"key": "D", "content": "0F02 0014H"}]', 'A', 2.0, '2026-408-15');
INSERT INTO question (id, subject, qtype, stem, options, answer, score, source) VALUES (2026016, 2, 1, '对于下列选项中给出的相关内容，不是．．由指令集体系结构规定的是 。', '[{"key": "A", "content": "指令集中是否包含输入和输出指令"}, {"key": "B", "content": "采用向量中断还是非向量中断方式"}, {"key": "C", "content": "采用段式还是页式虚拟存储管理方式"}, {"key": "D", "content": "指令流水线是否采用超级流水线技术"}]', 'D', 2.0, '2026-408-16');
INSERT INTO question (id, subject, qtype, stem, options, answer, score, source) VALUES (2026017, 2, 1, '下列指令中，执行后有可能按存放顺序执行其下一条指令的是 。 I. 条件跳转指令 II. 过程调用指令 III. 陷阱（Trap）指令 IV . 过程返回指令', '[{"key": "A", "content": "仅 I、II"}, {"key": "B", "content": "仅 I、IV"}, {"key": "C", "content": "仅 II、III"}, {"key": "D", "content": "仅 III、IV"}]', 'A', 2.0, '2026-408-17');
INSERT INTO question (id, subject, qtype, stem, options, answer, score, source) VALUES (2026018, 2, 1, '某计算机按字节编址，数据 Cache 共有 1024 行，采用 4 路组相联映射方式，主存块大小为 32B。 若需要访问主存地址为 1028 的 4 字节数据，则该数据所在主存块对应的Cache组号是', '[{"key": "A", "content": "4"}, {"key": "B", "content": "16"}, {"key": "C", "content": "32"}, {"key": "D", "content": "64"}]', 'C', 2.0, '2026-408-18');
INSERT INTO question (id, subject, qtype, stem, options, answer, score, source) VALUES (2026019, 2, 1, '某计算机按字节编址， 虚拟地址为 16 位， 页大小为 256B，页表项中包含装入位 （P）、页框号 （PPN） 等字段，TLB 采用 4 路组相联映射方式，共有 16 个TLB 表项，TLB 表项中包含标记 （Tag） 、有 效位（V）等字段。在 TLB 表项与主存页表同步后，若主存页表中页号 22 对应的页表项中P=0、 PPN=2AH，则下列选项中，不可能．．．出现在组号为 2 的TLB 表项中的是 。', '[{"key": "A", "content": "Tag = 05H、V = 1、PPN = 1CH"}, {"key": "B", "content": "Tag = 06H、V = 1、PPN = 2AH"}, {"key": "C", "content": "Tag = 16H、V = 0、PPN = 2AH"}, {"key": "D", "content": "Tag = 1AH、V = 0、PPN = 1CH"}]', 'A', 2.0, '2026-408-19');
INSERT INTO question (id, subject, qtype, stem, options, answer, score, source) VALUES (2026020, 2, 1, '在不考虑异常/中断处理和访存额外开销的前提下，下列关于数据通路结构与CPI 之间关系的叙述 中，正确的是 。 I. 单周期数据通路计算机的 CPI 等于 1 II. 多周期数据通路计算机的 CPI 大于 1 III. 流水线数据通路计算机的 CPI 等于 1', '[{"key": "A", "content": "仅 I、II"}, {"key": "B", "content": "仅 I、III"}, {"key": "C", "content": "仅 II、III"}, {"key": "D", "content": "I 、II、III"}]', 'A', 2.0, '2026-408-20');
