INSERT INTO question (id, subject, qtype, stem, options, answer, score, source) VALUES (2026027, 3, 1, '若进程 P 读、写数据的集合分别记为 R(P)和 W(P)，进程 Q 读、写数据的集合分别记为 R(Q)和 W(Q)，则进程 P 和 Q 并发执行时不会．．发生并发错误的充要条件是 。 I. W(P)∩W(Q) = ∅ II. R(P) ∩W(Q) = ∅ III. W(P) ∩R(Q) = ∅ IV . R(P) ∩W(Q) = ∅', '[{"key": "A", "content": "I、IV同时成立"}, {"key": "B", "content": "II 、III同时成立"}, {"key": "C", "content": "I 、II、III 同时成立"}, {"key": "D", "content": "I 、II、III、IV同时成立"}]', 'C', 2.0, '2026-408-27');
INSERT INTO question (id, subject, qtype, stem, options, answer, score, source) VALUES (2026028, 3, 1, '某 64 位系统采用三级页式存储管理方式，虚拟地址结构如下图所示。 保留（25 位） 一级页号（9 位） 二级页号（9 位） 三级页号（9 位） 页内偏移（12 位） 若各级页表项均占 8 字节，则进程的第三级页表占用的页框数最多是 。', '[{"key": "A", "content": "512"}, {"key": "B", "content": "32K"}, {"key": "C", "content": "256K"}, {"key": "D", "content": "128M"}]', 'C', 2.0, '2026-408-28');
