INSERT INTO question (id, subject, qtype, stem, options, answer, score, source) VALUES (2026036, 4, 1, '支持 VLAN划分的以太网交换机，已按端口划分了 2 个VLAN。VLAN 划分结果及部分端口连接 主机的 MAC 地址如下图所示。 下列具有不同目的 MAC 地址 （DA）和源 MAC 地址 （SA）的以太网帧 F1～F4 中，H3 会接收到 的是 。 F1：DA=00-1A-2B-3C-4D-03，SA=00-1A-2B-3C-4D-01 F2：DA=00-1A-2B-3C-4D-03，SA=00-1A-2B-3C-4D-05 F3：DA=FF-FF-FF-FF-FF-FF，SA=00-1A-2B-3C-4D-02 F4：DA=FF-FF-FF-FF-FF-FF，SA=00-1A-2B-3C-4D-06', '[{"key": "A", "content": "仅 F1、F2"}, {"key": "B", "content": "仅 F1、F3"}, {"key": "C", "content": "仅 F2、F4"}, {"key": "D", "content": "仅 F3、F4"}]', 'B', 2.0, '2026-408-36');
