INSERT INTO question (id, subject, qtype, stem, options, answer, score, source) VALUES (2026043, 2, 2, '（本题 10 分）某 16 位计算机C 按字节编址，通用寄存器 R0～R15 的编号为 0～15，存储器地 址为 16 位，采用定长指令字，指令格式有R、I和 M 型，如下所示。 格式 4 位 4 位 4 位 4 位 功能说明 R 型 0000 rt rs/num  op1 R[rt]←R[rt] op1 R[rs], R[rt]←R[rt] op1 num I型 op2 rt imm 8 R[rt] ←R[rt] op2 imm8 M 型 op3 offset R[ 0]←M[R[15]+offset], M[R[15]+offset]←R[0] 其中，op1 为 0001、0010 分别表示加、左移指令，op2 为 0100 表示加立即数指令，op3 为 1110、1111 分别表示取数、存数指令，R[r]表示寄存器 r中的内容，num 为移位位数，M[addr] 表示存储器地址 addr 中的内容。请回答下列问题。', NULL, NULL, 13.0, '2026-408-43');
INSERT INTO question (id, subject, qtype, stem, options, answer, score, source) VALUES (2026044, 2, 2, '（本题 13 分）假定题 43 中计算机C 的部分数据通路如题 44 图所示。 图中带箭头虚线表示控制信号，IR.rt、IR.rs 分别表示 IR 中的 rt、rs字段，IR11～0为 IR 中低 12 位。要求取指令周期内完成 PC 增量操作。请回答下列问题。', NULL, NULL, 10.0, '2026-408-44');
INSERT INTO question (id, subject, qtype, stem, options, answer, score, source) VALUES (2026045, 3, 2, '（本题 7 分）某系统采用基于抢占式优先权（优先权值越大优先权越高）和时间片轮转的CPU 调度算法，仅在时钟中断发生时才能抢占 CPU，时钟中断间隔时间为 10ms。每当进程进入就绪 队列时，其时间片大小均设置为 50ms。进程因时间片用完而再次进入就绪队列时，若其优先权 值大于 0，则优先权值减 1。进程因优先权低被抢占CPU 而再次进入就绪队列时，其优先权值不 变。优先权相同时，先进入就绪队列的进程先执行。假设系统中有 4 个进程P1～P4，各进程的 到达时刻、初始优先权值、所需的 CPU 执行时间如题 45 表所示。 题 45 表 进程 到达时刻 初始优先取值 CPU 执行时间 P1 10ms 3 95ms P2 10ms 4 20ms P3 12ms 2 40ms P4 14ms 5 60ms 请回答下列问题。', NULL, NULL, 7.0, '2026-408-45');
INSERT INTO question (id, subject, qtype, stem, options, answer, score, source) VALUES (2026046, 3, 2, '（本题 8 分）某基于索引节点（inode）的文件系统的目录项由文件名和索引节点号构成。磁盘 中存放了索引节点表、位图、目录等元数据以及文件数据，盘块大小为 4KB，盘块号占 4B。索 引节点表包含了所有文件的索引节点，位于从 100 号盘块开始的 4096 个连续盘块中，索引节点 号是索引节点在该表中的序号，从 0 开始编号。每个索引节点占 128B，包含直接地址项 5 个， 一次间接地址项、二次间接地址项、三次间接地址项各 1 个。磁盘块位图和索引节点位图分别用 于描述磁盘块和索引节点占用情况，0 表示未占用，1 表示已占用。某子目录树如题 46 图所示， 其中各文件的文件名和索引节点号如题 46 表所示，file大小为 30KB。 题 46 表 文件名 索引节点号 dir 100 dir1 201 file 1000 题 46 图 请回答下列问题。', NULL, NULL, 8.0, '2026-408-46');
INSERT INTO question (id, subject, qtype, stem, options, answer, score, source) VALUES (2026047, 4, 2, '（本题 9 分）人工智能（AI）是引领未来的战略性技术，其发展高度依赖强大的算力供给，通过 网络互联分散的算力中心，可以充分聚合算力资源，满足人工智能对大规模算力的需求，支撑人 工智能国家发展战略。某算力调度交易平台聚合各地的算力中心的算力，向用户提供算力服务的 示意场景如题 47 图所示。 算力用户C 向平台申请算力服务， 平台通过优化调度各算力中心算力， 向 C 授权使用算力中心 i 的算力，Si为算力中心 i 的负载均衡服务器，用于接收算力用户的计算 任务描述数据文件，并向算力中心 i 内部分派计算任务。为确保可靠传输，假设 C 建立一条 TCP 连接向服务器 Si上传一个总长度为2  000B的计算任务描述数据文件， 拥塞窗口初始阈值为8MSS， MSS=500B，Si对收到的每个 TCP段进行确认， 且确认段不封装数据， 接收窗口rwnd始终为1000 B， RTT=5ms。C 建立连接时选择的初始序号为 1000，Si选择的初始序号为 2000，SYN、ACK、FIN 为标志位，seq 为序号，ack_seq 为确认序号。在整个文件传输过程中未出现任何重传或报文段丢 失。 题 47 题图 请回答下列问题。', NULL, NULL, 9.0, '2026-408-47');
