INSERT INTO question_sub (question_id, seq, stem, score) VALUES (2022043, 1, '设 ALU 的输入端 A、B 及输出端 F 的最高位分别为 A15、B15 及 F15，FR 中的符号标志和溢 出标志分别为 SF 和 OF，则 SF 的逻辑表达式是什么？A 加 B、A 减 B 时 OF 的逻辑表达式分别 是什么？要求逻辑表达式的输入变量为 A15、B15 及 F15。', 0.0);
INSERT INTO question_sub (question_id, seq, stem, score) VALUES (2022043, 2, '为什么要设置暂存器 Y 和 Z？', 0.0);
INSERT INTO question_sub (question_id, seq, stem, score) VALUES (2022043, 3, '若 GPRs 的输入端 rs、rd 分别为所读、写的通用寄存器的编号，则 GPRs 中最多有多少个 通用寄存器？rs 和 rd 来自图中的哪个寄存器？已知 GPRs 内部有一个地址译码器和一个多路选 择器，rd 应连接地址译码器还是多路选择器？', 0.0);
INSERT INTO question_sub (question_id, seq, stem, score) VALUES (2022043, 4, '取指令阶段（不考虑 PC 增量操作）的控制信号序列是什么？若从发出主存读命令到主存 读出数据并传送到 MDR 共需 5 个时钟周期，则取指令阶段至少需要几个时钟周期？', 0.0);
