INSERT INTO question_sub (question_id, seq, stem, score) VALUES (2022044, 1, '每个扇区包含数据及其地址信息，地址信息分为 3 个字段。这 3 个字段的名称各是什么？ 对于该磁盘，各字段至少占多少位？', 0.0);
