INSERT INTO question_sub (question_id, seq, stem, score) VALUES (2023043, 4, '数组 a 占用多少主存块？假设上述程序段执行过程中数组 a 的访问不会和其他数据发生 Cache 访问冲突，则数组 a 的 Cache 命中率是多少？若将循环中 i 和 j 的次序按如下方式调换： for (j=0;j<64;j++) for (i=0;i<24;i++)a[i][j]=10; 则数组 a 的 Cache 命中率又是多少？', 0.0);
